import{_ as i,a0 as l,w as r,s as u,ao as o,I as a,x as e,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"我希望在 GNOME 中看到的 5 個微小而有用的功能 | LCTT x X-CMD","titleTemplate":false,"description":"我希望在 GNOME 中看到的 5 個微小而有用的功能 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我希望在 GNOME 中看到的 5 個微小而有用的功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我希望在 GNOME 中看到的 5 個微小而有用的功能 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20220108 5 Tiny Yet Useful Features I Would Like to See in GNOME in 2022","title":"我希望在 GNOME 中看到的 5 個微小而有用的功能","tag":"202201","desc":""},"relativePath":"202201/20220108 5 Tiny Yet Useful Features I Would Like to See in GNOME in 2022.md","filePath":"[post].md"}'),m={name:"202201/20220108 5 Tiny Yet Useful Features I Would Like to See in GNOME in 2022.md"};function d(f,t,N,O,w,M){const p=l("Link");return r(),u("div",null,[t[18]||(t[18]=o('<h1 id="我希望在-gnome-中看到的-5-個微小而有用的功能" tabindex="-1">我希望在 GNOME 中看到的 5 個微小而有用的功能 <a class="header-anchor" href="#我希望在-gnome-中看到的-5-個微小而有用的功能" aria-label="Permalink to “我希望在 GNOME 中看到的 5 個微小而有用的功能”">​</a></h1><blockquote><p>我知道對於聖誕願望清單來説已經太晚了，但我仍然想分享我希望在 GNOME 中看到的東西。</p></blockquote><p><img src="https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2022/01/gnome-wallpaper.png?w=1200&amp;ssl=1" alt=""></p><p>GNOME 是許多 Linux 發行版的默認桌面環境。它也是我最喜歡的一個，因為它提供了一種現代的桌面體驗。</p><p>但這並不意味着 GNOME 是完美的，不需要改進。事實上，這裏有幾個建議可以改善整個用户體驗。</p><h3 id="_1、方便的應用程序卸載選項" tabindex="-1">1、方便的應用程序卸載選項 <a class="header-anchor" href="#_1、方便的應用程序卸載選項" aria-label="Permalink to “1、方便的應用程序卸載選項”">​</a></h3><p>桌面 Linux 是碎片化的。為了增加混亂，連軟件包也是零零散散的。而最糟糕的是當你從系統中刪除一個應用程序時。</p><p>舉個例子，你要通過 DEB 包安裝一個應用程序，並使用 GNOME 軟件中心界面來安裝它。</p><p>但如果你不喜歡這個應用程序，想把它刪除呢？</p><p>你不會在軟件中心中找到該應用程序。相反，你得必須使用命令列的方法。</p>',10)),a("p",null,[t[1]||(t[1]=e("這還沒完。還有 Snap 和 ",-1)),n(p,{href:"https://itsfoss.com/what-is-flatpak/"},{default:s(()=>[...t[0]||(t[0]=[e("Flatpak",-1)])]),_:1}),t[2]||(t[2]=e(" 軟件包。如果你已經使用了其中之一，你必須先找出來，然後使用正確的命令才行。",-1))]),t[19]||(t[19]=o('<p>GNOME 採用了類似於 Android/iOS 的方法，將應用程序顯示在一個網格中，並將它們組織在文件夾中。移動操作系統為用户提供了一種方式，即按住圖標並刪除應用程序。如果能有一個類似的選項，右鍵點擊應用程序圖標並選擇卸載，那就更好了。</p><p><img src="https://i2.wp.com/news.itsfoss.com/wp-content/uploads/2022/01/Remove-application-option-gnome.png?w=800&amp;ssl=1" alt=""></p><p>這樣，終端用户就不用管所安裝的應用程序是 Deb 包還是 Snap 包。沒有必要為此進入終端，而且它就發生在訪問應用程序地方，這不是挺好嗎？</p><p>Linux Mint Cinnamon 版有這樣的功能，你在菜單中右鍵點擊一個應用程序條目，選擇刪除它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/08/removing-google-chrome-from-mint.webp?resize=799%2C562&amp;ssl=1" alt="Linux Mint Cinnamon 中可以使用右鍵刪除選項"></p><p>如果 Cinnamon 能做到，GNOME 應該也能做到，對嗎？</p><h3 id="_2、在應用程序商店中設置默認軟件源" tabindex="-1">2、在應用程序商店中設置默認軟件源 <a class="header-anchor" href="#_2、在應用程序商店中設置默認軟件源" aria-label="Permalink to “2、在應用程序商店中設置默認軟件源”">​</a></h3><p>如果一個應用程序有多種格式，GNOME 軟件中心可以讓你選擇軟件源。至少這是我在 Fedora 的 GNOME 軟件中看到的，但在 Ubuntu 中沒有。</p><p><img src="https://i1.wp.com/news.itsfoss.com/wp-content/uploads/2022/01/choosing-software-source-gnome.png?resize=1568%2C1007&amp;ssl=1" alt=""></p><p>假設有人在軟件中心同時添加了 Flatpak 和 Snap 支持，而一個應用程序在 Flatpak、Snap 和軟件包管理器（apt、DNF 等）中都可用，它可能會在搜索結果中顯示多次。</p><p>如果能夠設置一個默認的打包格式，使其優先於其他格式，那就更好了。如果你把 Flatpak 作為默認，它就不會顯示 Snap 版本，默認只安裝 Flatpak 版本。</p><h3 id="_3、跨系統同步安裝的應用程序" tabindex="-1">3、跨系統同步安裝的應用程序 <a class="header-anchor" href="#_3、跨系統同步安裝的應用程序" aria-label="Permalink to “3、跨系統同步安裝的應用程序”">​</a></h3><p>這一點可能取決於發行版情況，從技術和策略的角度看都比較複雜。</p><p>安卓、iOS、macOS 和 Windows 都有這個功能，這樣可以更容易開始使用新設備或重置的同一設備。你從他們的官方應用程序商店安裝的應用程序與你的個人資料相關聯。你重新安裝/重置操作系統，或者在一個新系統上，登錄應用程序商店，它就會顯示你以前使用過的應用程序。</p><p>在 Linux 上，如果你由於某種原因重新安裝系統，你就會失去你所安裝的應用程序。當然，你可以重新安裝它們，但你也必須回憶起你以前安裝的應用程序。</p><p>我記得 Ubuntu 曾經有個 Ubuntu One 雲，我以為他們會推出這個功能，但他們關閉了這個雲服務。然而，Ubuntu One 仍然活着，並被用作 SSO 登錄。事實上，你可以在 Ubuntu 軟件中心看到 Ubuntu One 的登錄選項，但它並沒有做任何事情。</p><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/01/sign-in-ubuntu-software-center.png?resize=1568%2C836&amp;ssl=1" alt="Ubuntu 軟件中心的登錄選項"></p><p>知道你之前從 GNOME 軟件中心安裝了哪些軟件，將使電腦的格式化和在電腦之間的移動更加容易。你不覺得嗎？</p><p>當然，許多 Linux 用户不一定依靠軟件中心來獲取應用程序，但這對一些人來説可能是一個有用的功能。</p><h3 id="_4、面部解鎖和-或指紋登錄" tabindex="-1">4、面部解鎖和/或指紋登錄 <a class="header-anchor" href="#_4、面部解鎖和-或指紋登錄" aria-label="Permalink to “4、面部解鎖和/或指紋登錄”">​</a></h3><p>我喜歡用密碼登錄並解鎖 Windows 的方式。是的，我偶爾會使用 Windows。不，不是用來玩遊戲，而是用超高清觀看流媒體內容。過去幾周我用得比較頻繁，因為我在另一個城市，我必須依靠我的筆記本電腦來觀看 4K 的 Netflix，而不是使用我的電視。</p><p>輸入整個 8 到 10 個字符的長密碼，加上特殊字符，總覺得是件麻煩事。值得慶幸的是，我的筆記本電腦有一個指紋識別器，但不是每個人都有這種奢侈。</p><p>對於許多已經習慣於在移動設備上使用這些方法的用户來説，使用指紋或面部來解鎖設備可能會很好。</p><p>已經有一些項目允許你在 Linux 上使用面部解鎖，GNOME 確實可以考慮將其加入到其產品中。</p><h3 id="_5、帶回-添加新文檔-選項" tabindex="-1">5、帶回“添加新文檔”選項 <a class="header-anchor" href="#_5、帶回-添加新文檔-選項" aria-label="Permalink to “5、帶回“添加新文檔”選項”">​</a></h3><p>幾年前，GNOME 刪除了從右鍵菜單中創建一個新文檔的功能。</p><p>現在仍然可以實現這個功能。你必須先在你的主目錄的 Templates 文件夾中創建一個模板文檔。然後所有的模板文檔都可以在右鍵菜單中找到。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/09/templates-in-ubuntu.png?resize=800%2C479&amp;ssl=1" alt=""></p><p>但這本應是一個默認功能。人們不應該胡亂擺弄而試圖找出“創建新文檔”選項的去處。</p><p>現在是時候讓 GNOME 恢復這個功能了。</p><h3 id="你希望在-gnome-中看到什麼功能" tabindex="-1">你希望在 GNOME 中看到什麼功能？ <a class="header-anchor" href="#你希望在-gnome-中看到什麼功能" aria-label="Permalink to “你希望在 GNOME 中看到什麼功能？”">​</a></h3><p>由於我主要使用 Ubuntu，它的定製 GNOME 與原生 GNOME 不同。原生 GNOME 也應該把小程序指示器帶回來，這樣像 Dropbox 等應用程序就可以快速訪問。</p><p>GNOME 開發者不太可能關注像我們這樣的普通 Linux 用户的想法，但我還是要問問你怎麼看。</p><p>你希望在 GNOME 或桌面 Linux 中看到什麼新功能？你也可以分享一些你最喜歡的、已經從 GNOME 中刪除的，但你希望它們能重新出現的功能。</p><hr>',35)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),n(p,{href:"https://news.itsfoss.com/gnome-features-i-want/"},{default:s(()=>[...t[3]||(t[3]=[e("https://news.itsfoss.com/gnome-features-i-want/",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=e("作者：",-1)),n(p,{href:"https://news.itsfoss.com/author/root/"},{default:s(()=>[...t[5]||(t[5]=[e("Abhishek",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),n(p,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),n(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),n(p,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const g=i(m,[["render",d]]);export{b as __pageData,g as default};
